import{_ as o,o as a,c as i,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Divisão Unificada dos Reinos de Cultivo","description":"","frontmatter":{},"headers":[],"relativePath":"pt/14-修炼境界统一划分.md","filePath":"pt/14-修炼境界统一划分.md","lastUpdated":1789183869000}'),r={name:"pt/14-修炼境界统一划分.md"};function n(s,e,t,l,c,u){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="divisao-unificada-dos-reinos-de-cultivo" tabindex="-1">Divisão Unificada dos Reinos de Cultivo <a class="header-anchor" href="#divisao-unificada-dos-reinos-de-cultivo" aria-label="Permalink to &quot;Divisão Unificada dos Reinos de Cultivo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>14</td></tr><tr><td>Módulo</td><td>Leis do Universo e Sistemas de Cultivo</td></tr><tr><td>Palavras-chave</td><td>Divisão de Reinos, Padrão Unificado, Nove Reinos, Comparação entre Sistemas, Certificação de Âncora</td></tr></tbody></table><h2 id="i-necessidade-da-divisao-unificada-de-reinos" tabindex="-1">I. Necessidade da Divisão Unificada de Reinos <a class="header-anchor" href="#i-necessidade-da-divisao-unificada-de-reinos" aria-label="Permalink to &quot;I. Necessidade da Divisão Unificada de Reinos&quot;">​</a></h2><p>Antes do estabelecimento da civilização simbiótica das Âncoras, existiam milhares de sistemas de cultivo no Heng Yuan Zhou, e cada sistema tinha seu próprio padrão independente de divisão de reinos. Esse sistema caótico de reinos levou a uma série de problemas: era difícil comparar o poder entre cultivadores de diferentes sistemas, faltava uma linguagem comum para a comunicação e colaboração entre sistemas, faltava uma base unificada para a alocação de recursos e a avaliação do status social, e até mesmo ocorreu o grave fenômeno de injustiça de &quot;mesmo reino, poder diferente&quot;.</p><p>Após o estabelecimento da civilização simbiótica das Âncoras, para resolver esse problema, liderado pelo &quot;Comitê de Padrões de Cultivo&quot; subordinado ao Parlamento Republicano de Todas as Raças, em conjunto com os cultivadores representantes dos trezentos sistemas, após longa pesquisa e argumentação, foi formulado este &quot;Padrão de Divisão Unificada dos Reinos de Cultivo&quot;. Este padrão não se baseia nos nomes de reinos de nenhum sistema único, mas sim em quatro dimensões como indicadores centrais: a profundidade de compreensão do cultivador sobre as leis originais do universo, a precisão do controle de energia, o grau de evolução da consciência e o grau de contribuição para a rede simbiótica, estabelecendo um sistema de divisão de reinos universal entre sistemas.</p><p>O princípio central da divisão unificada de reinos é &quot;valorizar a substância em detrimento do nome&quot;: independentemente de qual sistema o cultivador use ou qual nome de reino ele tenha, desde que sua substância atinja o nível correspondente do padrão unificado, ele é reconhecido como pertencente àquele reino. Este princípio garante a justiça e a objetividade da avaliação de reinos.</p><h2 id="ii-visao-geral-dos-nove-reinos" tabindex="-1">II. Visão Geral dos Nove Reinos <a class="header-anchor" href="#ii-visao-geral-dos-nove-reinos" aria-label="Permalink to &quot;II. Visão Geral dos Nove Reinos&quot;">​</a></h2><p>O padrão de divisão unificada de reinos divide o processo de evolução do cultivador em nove reinos, do mais baixo ao mais alto, em ordem:</p><table tabindex="0"><thead><tr><th>Número do Reino</th><th>Nome do Reino</th><th>Característica Central</th><th>Correspondência Aproximada com os Reinos das Três Bases Originais</th><th>Papel Social</th></tr></thead><tbody><tr><td>Primeiro Reino</td><td>Reino de Percepção de Energia</td><td>Percebe inicialmente a existência de energia e leis universais, inicia o cultivo formal</td><td>Visão Inicial / Percepção da Vida / Reconhecimento do Espaço</td><td>Iniciante</td></tr><tr><td>Segundo Reino</td><td>Reino de Condensação de Energia</td><td>Capaz de absorver e condensar energia de forma estável, estabelece o ciclo interno básico</td><td>Dedução / Ciclo / Controle do Espaço</td><td>Cultivador Iniciante</td></tr><tr><td>Terceiro Reino</td><td>Reino de Transformação de Energia</td><td>A purificação de energia atinge um nível elevado, capaz de transformar energia em várias aplicações</td><td>Iteração / Vida Contínua / Transformação do Espaço</td><td>Cultivador Intermediário</td></tr><tr><td>Quarto Reino</td><td>Reino de Energia Jurisprudencial</td><td>Começa a compreender e controlar as leis, energia e leis se fundem inicialmente</td><td>Fusão / Transformação da Vida / Espaço Jurisprudencial</td><td>Cultivador Avançado</td></tr><tr><td>Quinto Reino</td><td>Reino de Energia do Dao</td><td>Tem uma compreensão profunda das leis de um determinado campo, forma o &quot;Dao&quot; pessoal</td><td>Original / Vida Original / Espaço Original</td><td>Cultivador Mestre</td></tr><tr><td>Sexto Reino</td><td>Reino de União com o Dao</td><td>O Dao pessoal e as leis originais do universo se fundem profundamente, cada gesto está em harmonia com o Dao</td><td>Além do Quinto Reino de um único sistema</td><td>Cultivador Grão-Mestre</td></tr><tr><td>Sétimo Reino</td><td>Reino de Rompimento de Fronteiras</td><td>Capaz de romper as limitações das leis de plano, realizar operações estáveis entre planos</td><td>—</td><td>Ser Poderoso de Nível de Plano</td></tr><tr><td>Oitavo Reino</td><td>Reino de Criação</td><td>Capaz de criar mundos completos e sistemas de leis em espaços isolados</td><td>—</td><td>Ser Poderoso de Nível Mundial</td></tr><tr><td>Nono Reino</td><td>Reino Original</td><td>Toca a origem do universo, capaz de participar do ajuste fino e otimização das leis universais</td><td>—</td><td>Ser Poderoso de Nível Cósmico</td></tr></tbody></table><p>Entre os nove reinos, o primeiro ao quinto reino são os &quot;Cinco Reinos de Cultivo Comum&quot;, que a maioria dos cultivadores pode alcançar por meio de esforço; o sexto ao nono reino são os &quot;Quatro Reinos de Cultivo Sagrado&quot;, que exigem talento, oportunidade e esforço extremamente elevados para serem alcançados, e o rompimento de cada reino é um evento cósmico de grande importância.</p><h2 id="iii-padroes-detalhados-de-cada-reino" tabindex="-1">III. Padrões Detalhados de Cada Reino <a class="header-anchor" href="#iii-padroes-detalhados-de-cada-reino" aria-label="Permalink to &quot;III. Padrões Detalhados de Cada Reino&quot;">​</a></h2><h3 id="_3-1-primeiro-reino-reino-de-percepcao-de-energia" tabindex="-1">3.1 Primeiro Reino: Reino de Percepção de Energia <a class="header-anchor" href="#_3-1-primeiro-reino-reino-de-percepcao-de-energia" aria-label="Permalink to &quot;3.1 Primeiro Reino: Reino de Percepção de Energia&quot;">​</a></h3><p>O Reino de Percepção de Energia é o ponto de partida do cultivo, e seu núcleo é a &quot;percepção&quot;. Os padrões para alcançar o Reino de Percepção de Energia incluem:</p><ul><li>Capaz de perceber de forma estável a energia livre no universo (energia espiritual, poder das leis, etc.)</li><li>Capaz de absorver uma pequena quantidade de energia para dentro do corpo por meio de métodos básicos de cultivo</li><li>Estabelece uma consciência inicial de percepção de energia, capaz de distinguir diferentes tipos de energia</li><li>A qualidade física tem uma melhoria inicial devido à infusão de energia</li></ul><p>Os cultivadores do Reino de Percepção de Energia são &quot;iniciantes&quot; na sociedade, e sua principal tarefa é construir a base e encontrar o sistema de cultivo adequado para si. O rompimento do Reino de Percepção de Energia geralmente requer de algumas semanas a alguns meses de cultivo formal.</p><h3 id="_3-2-segundo-reino-reino-de-condensacao-de-energia" tabindex="-1">3.2 Segundo Reino: Reino de Condensação de Energia <a class="header-anchor" href="#_3-2-segundo-reino-reino-de-condensacao-de-energia" aria-label="Permalink to &quot;3.2 Segundo Reino: Reino de Condensação de Energia&quot;">​</a></h3><p>O núcleo do Reino de Condensação de Energia é a &quot;condensação&quot;. Os padrões para alcançar o Reino de Condensação de Energia incluem:</p><ul><li>Capaz de absorver energia universal de forma estável e condensá-la em reserva de energia utilizável dentro do corpo</li><li>Estabelece o sistema de ciclo interno básico, a energia pode circular dentro do corpo seguindo caminhos específicos</li><li>Capaz de usar a energia condensada para aplicações básicas de ataque-defesa ou auxiliares</li><li>A pureza da energia atinge o padrão básico, não contém impurezas excessivas</li></ul><p>Os cultivadores do Reino de Condensação de Energia já possuem a identidade básica de cultivador e podem participar de algumas tarefas de cultivo de baixo nível e serviços sociais. O rompimento do Reino de Condensação de Energia geralmente requer de alguns meses a alguns anos de cultivo.</p><h3 id="_3-3-terceiro-reino-reino-de-transformacao-de-energia" tabindex="-1">3.3 Terceiro Reino: Reino de Transformação de Energia <a class="header-anchor" href="#_3-3-terceiro-reino-reino-de-transformacao-de-energia" aria-label="Permalink to &quot;3.3 Terceiro Reino: Reino de Transformação de Energia&quot;">​</a></h3><p>O núcleo do Reino de Transformação de Energia é a &quot;transformação&quot;. Os padrões para alcançar o Reino de Transformação de Energia incluem:</p><ul><li>A purificação de energia atinge um nível elevado, capaz de transformar um tipo de energia em outro</li><li>Capaz de realizar interação inicial entre energia e matéria (como anexar energia a objetos, moldar energia, etc.)</li><li>O ciclo interno é estável e eficiente, a velocidade de recuperação de energia aumenta significativamente</li><li>Começa a perceber a existência e o funcionamento das leis</li></ul><p>Os cultivadores do Reino de Transformação de Energia são a força central da sociedade, podendo ocupar cargos como instrutores intermediários, técnicos e gerentes de base. O rompimento do Reino de Transformação de Energia geralmente requer de alguns anos a mais de uma década de cultivo.</p><h3 id="_3-4-quarto-reino-reino-de-energia-jurisprudencial" tabindex="-1">3.4 Quarto Reino: Reino de Energia Jurisprudencial <a class="header-anchor" href="#_3-4-quarto-reino-reino-de-energia-jurisprudencial" aria-label="Permalink to &quot;3.4 Quarto Reino: Reino de Energia Jurisprudencial&quot;">​</a></h3><p>O núcleo do Reino de Energia Jurisprudencial é a &quot;lei&quot;. Os padrões para alcançar o Reino de Energia Jurisprudencial incluem:</p><ul><li>Capaz de compreender e controlar inicialmente as leis básicas de um determinado campo</li><li>Energia e leis se fundem inicialmente, produzindo a forma de energia de nível mais elevado chamada &quot;poder jurídico&quot;</li><li>Capaz de realizar técnicas e habilidades baseadas em leis</li><li>A força da consciência aumenta significativamente, capaz de realizar deduções profundas e meditação por longos períodos</li></ul><p>Os cultivadores do Reino de Energia Jurisprudencial são talentos de alto nível na sociedade, podendo ocupar cargos como instrutores avançados, especialistas técnicos e gerentes intermediários. O rompimento do Reino de Energia Jurisprudencial geralmente requer de mais de uma década a algumas décadas de cultivo, sendo o primeiro grande gargalo na vida de muitos cultivadores.</p><h3 id="_3-5-quinto-reino-reino-de-energia-do-dao" tabindex="-1">3.5 Quinto Reino: Reino de Energia do Dao <a class="header-anchor" href="#_3-5-quinto-reino-reino-de-energia-do-dao" aria-label="Permalink to &quot;3.5 Quinto Reino: Reino de Energia do Dao&quot;">​</a></h3><p>O núcleo do Reino de Energia do Dao é a &quot;realização do Dao&quot;. Os padrões para alcançar o Reino de Energia do Dao incluem:</p><ul><li>Tem uma compreensão sistemática e profunda das leis de um determinado campo, forma o &quot;Dao&quot; único e pessoal</li><li>O Dao pessoal ressoa com as leis universais, capaz de mobilizar o poder das leis em uma ampla gama</li><li>Energia e leis se fundem profundamente, cada gesto contém o poder das leis</li><li>A consciência evolui para um nível elevado, capaz de realizar percepção de consciência entre planos</li></ul><p>Os cultivadores do Reino de Energia do Dao são os &quot;mestres&quot; da civilização, tendo autoridade em seus respectivos campos, podendo ocupar cargos como consultores de nível civilizacional, grandes instrutores e gerentes avançados. O rompimento do Reino de Energia do Dao exige talento e compreensão extremamente elevados, e muitos cultivadores não conseguem alcançá-lo ao longo de toda a vida.</p><h3 id="_3-6-sexto-reino-reino-de-uniao-com-o-dao" tabindex="-1">3.6 Sexto Reino: Reino de União com o Dao <a class="header-anchor" href="#_3-6-sexto-reino-reino-de-uniao-com-o-dao" aria-label="Permalink to &quot;3.6 Sexto Reino: Reino de União com o Dao&quot;">​</a></h3><p>O núcleo do Reino de União com o Dao é a &quot;união com o Dao&quot;. Os padrões para alcançar o Reino de União com o Dao incluem:</p><ul><li>O Dao pessoal e as leis originais do universo se fundem profundamente, atingindo o estado de &quot;união entre o céu e o homem&quot;</li><li>Capaz de reescrever o modo de funcionamento das leis locais em uma ampla gama</li><li>A forma de vida começa a evoluir para uma dimensão mais elevada, libertando-se parcialmente das limitações do corpo material</li><li>Capaz de criar um domínio pessoal estável (domínio jurídico)</li></ul><p>Os cultivadores do Reino de União com o Dao são os &quot;grãos-mestres&quot; da civilização, sendo as figuras de destaque em cada campo, tendo uma influência importante na direção do desenvolvimento da civilização. O rompimento do Reino de União com o Dao é um evento cósmico, exigindo a cooperação de tempo, lugar e pessoas.</p><h3 id="_3-7-setimo-reino-reino-de-rompimento-de-fronteiras" tabindex="-1">3.7 Sétimo Reino: Reino de Rompimento de Fronteiras <a class="header-anchor" href="#_3-7-setimo-reino-reino-de-rompimento-de-fronteiras" aria-label="Permalink to &quot;3.7 Sétimo Reino: Reino de Rompimento de Fronteiras&quot;">​</a></h3><p>O núcleo do Reino de Rompimento de Fronteiras é o &quot;rompimento de fronteiras&quot;. Os padrões para alcançar o Reino de Rompimento de Fronteiras incluem:</p><ul><li>Capaz de romper as limitações das leis de plano, realizar travessia entre planos sem o suporte de âncoras</li><li>Capaz de operar a membrana do plano, como abrir canais entre planos, reparar fissuras de plano, etc.</li><li>O domínio pessoal pode ser expandido para um pequeno espaço independente</li><li>A forma de vida torna-se ainda mais dimensional, capaz de sobreviver nos ambientes legais de diferentes planos</li></ul><p>Os seres poderosos do Reino de Rompimento de Fronteiras são existências de &quot;nível de plano&quot;, capazes de assumir independentemente tarefas e responsabilidades de nível de plano. O rompimento do Reino de Rompimento de Fronteiras é extremamente difícil, e o número de cultivadores que alcançam este reino em todo o Heng Yuan Zhou é limitado.</p><h3 id="_3-8-oitavo-reino-reino-de-criacao" tabindex="-1">3.8 Oitavo Reino: Reino de Criação <a class="header-anchor" href="#_3-8-oitavo-reino-reino-de-criacao" aria-label="Permalink to &quot;3.8 Oitavo Reino: Reino de Criação&quot;">​</a></h3><p>O núcleo do Reino de Criação é a &quot;criação&quot;. Os padrões para alcançar o Reino de Criação incluem:</p><ul><li>Capaz de criar mundos completos em espaços isolados, incluindo matéria, energia, leis e vida</li><li>Capaz de projetar e formular o sistema de leis básicas do novo mundo</li><li>O domínio pessoal pode ser expandido para um mundo completo</li><li>A forma de vida aproxima-se de uma existência dimensional elevada, capaz de se manifestar em múltiplos planos simultaneamente</li></ul><p>Os seres poderosos do Reino de Criação são existências de &quot;nível mundial&quot;, e os mundos por eles criados podem ser usados como recursos de cultivo, locais de experimentação, abrigos civilizacionais, etc. O rompimento do Reino de Criação é um dos eventos mais raros do universo.</p><h3 id="_3-9-nono-reino-reino-original" tabindex="-1">3.9 Nono Reino: Reino Original <a class="header-anchor" href="#_3-9-nono-reino-reino-original" aria-label="Permalink to &quot;3.9 Nono Reino: Reino Original&quot;">​</a></h3><p>O núcleo do Reino Original é a &quot;origem&quot;. Os padrões para alcançar o Reino Original incluem:</p><ul><li>Toca as leis originais do universo, capaz de compreender as leis últimas de funcionamento do universo</li><li>Capaz de participar do ajuste fino e otimização das leis universais, influenciando a direção da evolução do universo</li><li>A forma de vida estabelece uma conexão profunda com a origem do universo, sendo quase imortal</li><li>Capaz de mobilizar o poder original em escala cósmica</li></ul><p>Os seres poderosos do Reino Original são existências de &quot;nível cósmico&quot;, sendo as forças mais proeminentes no Heng Yuan Zhou. Os cultivadores que alcançam o Reino Original são geralmente chamados de &quot;seres poderosos supremos de plano&quot;, e são o grupo-alvo central da &quot;Estratégia de Ativação de 20%&quot; da civilização simbiótica.</p><h2 id="iv-mecanismo-de-certificacao-de-reinos" tabindex="-1">IV. Mecanismo de Certificação de Reinos <a class="header-anchor" href="#iv-mecanismo-de-certificacao-de-reinos" aria-label="Permalink to &quot;IV. Mecanismo de Certificação de Reinos&quot;">​</a></h2><p>Para garantir a justiça e a precisão da avaliação de reinos, a civilização simbiótica estabeleceu um rigoroso mecanismo de certificação de reinos:</p><ol><li><strong>Monitoramento Automático de Âncoras</strong>: Após o cultivador se conectar à rede de âncoras, a âncora monitora continuamente indicadores como seu nível de energia, compreensão de leis e força de consciência, e quando os indicadores atingem o padrão de um novo reino, ela avisa automaticamente</li><li><strong>Exame do Comitê de Padrões</strong>: Para o rompimento de reinos a partir do quarto reino, é necessário que o Comitê de Padrões de Cultivo organize um exame formal, que inclui três aspectos: teste teórico, teste prático e avaliação de contribuição</li><li><strong>Período de Publicidade e Oposição</strong>: Após a aprovação no exame, é realizada uma publicidade de trinta dias; durante o período de publicidade, qualquer vida pode apresentar oposição, e se a oposição for procedente, é necessário um novo exame</li><li><strong>Emissão de Certificado de Reino</strong>: Após a publicidade sem oposições, a rede de âncoras emite o certificado de reino unificado, e as informações do certificado são registradas no banco de dados da civilização</li></ol><h2 id="v-correspondencia-entre-reinos-e-direitos-deveres-sociais" tabindex="-1">V. Correspondência entre Reinos e Direitos-Deveres Sociais <a class="header-anchor" href="#v-correspondencia-entre-reinos-e-direitos-deveres-sociais" aria-label="Permalink to &quot;V. Correspondência entre Reinos e Direitos-Deveres Sociais&quot;">​</a></h2><p>Cultivadores de diferentes reinos desfrutam de diferentes direitos e assumem diferentes deveres na civilização simbiótica:</p><table tabindex="0"><thead><tr><th>Reino</th><th>Direitos Centrais</th><th>Deveres Centrais</th></tr></thead><tbody><tr><td>Reino de Percepção - Condensação de Energia</td><td>Obtenção gratuita de recursos básicos de cultivo, direito de uso de locais públicos de cultivo</td><td>Cumprir a ética do cultivo, participar de serviços comunitários básicos</td></tr><tr><td>Reino de Transformação - Energia Jurisprudencial</td><td>Direito de alocação de recursos avançados, direito de solicitação de qualificação de instrutor, direito de circulação entre regiões</td><td>Instruir cultivadores iniciantes, participar de pesquisa tecnológica ou serviços sociais</td></tr><tr><td>Reino de Energia do Dao - União com o Dao</td><td>Direito de alocação de recursos de alto nível, direito de acesso de alto nível às âncoras, direito de participação nas decisões civilizacionais</td><td>Assumir projetos de pesquisa de nível civilizacional, manter a estabilidade das âncoras regionais</td></tr><tr><td>Reino de Rompimento de Fronteiras - Criação</td><td>Direito de alocação de recursos de nível de plano, direito de criação de espaços independentes, direito de participação em assuntos de plano</td><td>Assumir tarefas de nível de plano, manter a estabilidade da membrana do plano, participar de assuntos entre planos</td></tr><tr><td>Reino Original</td><td>Direito de alocação de recursos de nível cósmico, direito de participação no ajuste fino das leis, direito de participação nas decisões supremas da civilização</td><td>Manter a estabilidade geral do universo, orientar a direção da evolução da civilização, cultivar talentos de reserva</td></tr></tbody></table><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O padrão de divisão unificada dos reinos de cultivo é uma das infraestruturas do sistema de cultivo da civilização simbiótica das Âncoras. Ele fornece uma &quot;medida comum&quot; para os trezentos sistemas de cultivo, tornando possível a comunicação, colaboração e competição entre sistemas, e também fornece uma base objetiva para a alocação de recursos, governança social e cultivo de talentos. A divisão dos nove reinos não visa criar diferenças de classe, mas sim identificar claramente o estágio de evolução de cada cultivador, fornecendo-lhe o suporte e a orientação mais adequados. A elevação do reino não é o ponto final, mas sim um novo ponto de partida para a evolução simbiótica de nível mais elevado.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Visão Geral dos Trezentos Sistemas de Cultivo Originais)</li><li>17-位面至高强者标准 (Padrão dos Seres Poderosos Supremos de Plano)</li><li>29-共生度评估体系 (Sistema de Avaliação do Grau de Simbiose)</li></ul>',57)])])}const v=o(r,[["render",n]]);export{p as __pageData,v as default};
